package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// The input is processed line by line. Each line is rendered as:
//
//   - a header: 1-6 leading '#' characters followed by a space, rendered as
//     <h1> through <h6>. Lines with 7 or more leading '#' characters are not
//     headers and are rendered as paragraph text.
//   - a list item: a leading "* ", rendered as a <li> inside a <ul>.
//   - a paragraph: anything else, rendered inside a single <p>.
//
// Before the lines are processed, the first "__" pair and the first "_" pair
// in the whole input are converted to <strong> and <em> respectively.
//
// Refactoring notes: the original implementation walked the input one
// character at a time while juggling several piece of state (a running
// header level, a list counter, an "he" flag, and LastIndex lookups) to
// decide what to emit. That made the block boundaries (where a <ul> or <p>
// opens and closes) hard to follow. This version splits the input into lines
// up front and classifies each line, which makes the same output rules
// explicit and keeps the output byte-for-byte identical for the supported
// syntax.
func Render(markdown string) string {
	lines := strings.Split(renderEmphasis(markdown), "\n")
	// Trailing newlines produce empty lines that would render nothing; drop
	// them so they do not affect the output.
	for len(lines) > 1 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	r := &renderer{}
	for _, line := range lines {
		r.renderLine(line)
	}
	r.closeList()
	r.closeParagraph()
	return r.html.String()
}

// renderer accumulates the HTML output and tracks which block element is
// currently open, so an open block is closed before a new one starts.
type renderer struct {
	html          strings.Builder
	listOpen      bool
	paragraphOpen bool
}

// renderLine renders a single line, closing any open block that cannot
// contain the new line's content.
func (r *renderer) renderLine(line string) {
	if level, content, ok := parseHeader(line); ok {
		r.closeList()
		r.closeParagraph()
		fmt.Fprintf(&r.html, "<h%d>%s</h%d>", level, content, level)
		return
	}
	if isListItem(line) {
		r.closeParagraph()
		if !r.listOpen {
			r.html.WriteString("<ul>")
			r.listOpen = true
		}
		r.html.WriteString("<li>" + listItemText(line) + "</li>")
		return
	}
	r.closeList()
	if r.paragraphOpen {
		// Continuation of the paragraph started on a previous line.
		r.html.WriteString("\n")
	} else {
		r.html.WriteString("<p>")
		r.paragraphOpen = true
	}
	r.html.WriteString(line)
}

// closeList closes an open <ul>, if any.
func (r *renderer) closeList() {
	if r.listOpen {
		r.html.WriteString("</ul>")
		r.listOpen = false
	}
}

// closeParagraph closes an open <p>, if any.
func (r *renderer) closeParagraph() {
	if r.paragraphOpen {
		r.html.WriteString("</p>")
		r.paragraphOpen = false
	}
}

// renderEmphasis converts markdown emphasis markers to HTML tags.
//
// Only the first pair of each marker type is converted: the first "__" pair
// becomes <strong> and the first "_" pair becomes <em>. "__" is converted
// before "_" so that bold markers are not mistaken for emphasis markers.
func renderEmphasis(text string) string {
	text = replaceFirstPair(text, "__", "<strong>", "</strong>")
	return replaceFirstPair(text, "_", "<em>", "</em>")
}

// replaceFirstPair wraps the first pair of marker occurrences in the given
// tags: the first occurrence becomes the opening tag and the second one the
// closing tag.
func replaceFirstPair(text, marker, open, close string) string {
	text = strings.Replace(text, marker, open, 1)
	return strings.Replace(text, marker, close, 1)
}

// parseHeader reports whether line is a header line, that is, 1-6 leading
// '#' characters followed by a space. It returns the header level and the
// text that follows the marker.
func parseHeader(line string) (level int, content string, ok bool) {
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 || level > 6 || level == len(line) || line[level] != ' ' {
		return 0, "", false
	}
	return level, line[level+1:], true
}

// isListItem reports whether line is a list item, that is, a line starting
// with "* ".
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

// listItemText returns the text of a list item with the "* " marker removed.
func listItemText(line string) string {
	return strings.TrimPrefix(line, "* ")
}

